+import { get } from "./request";
+
+export function fetchOrders(params = {}) {
+  const query = new URLSearchParams(params).toString();
+  return get(`/api/orders${query ? `?${query}` : ""}`);
+}
+
+export function fetchOrder(id) {
+  return get(`/api/orders/${id}`);
+}

